<section class="container section-top"><?php ff_heading('gallery','A visual exploration of training and movement.'); ?><div class="notice compact"><p><?=e(t('gallery_intro'))?></p></div><form class="filter-bar" method="get"><input type="hidden" name="page" value="gallery"><label><span><?=e(t('album'))?></span><select name="category"><option value=""><?=e(t('all_albums'))?></option><?php foreach($categories??['equipment','facilities','training','wellness'] as $cat): $v=is_array($cat)?$cat['category']:$cat; ?><option value="<?=e($v)?>" <?=($_GET['category']??'')===$v?'selected':''?>><?=e(t($v))?></option><?php endforeach ?></select></label><button class="button dark" type="submit"><?=e(t('filter'))?></button><a href="<?=e(url('gallery'))?>" class="text-link"><?=e(t('clear_filters'))?></a></form><div class="gallery-grid"><?php foreach($items??[] as $item): ?><figure><button class="gallery-trigger" data-gallery-src="<?=e(ff_image($item))?>" data-gallery-alt="<?=e(ff_image_alt($item))?>" data-gallery-caption="<?=e($item['title'].' — '.($item['summary']??''))?>" aria-label="<?=e(t('enlarge_image').': '.$item['title'])?>"><img src="<?=e(ff_image($item))?>" alt="<?=e(ff_image_alt($item))?>" width="800" height="620" loading="lazy"><span aria-hidden="true">↗</span></button><figcaption><strong><?=e($item['title'])?></strong><span><?=e($item['summary']??'')?></span></figcaption></figure><?php endforeach ?></div><?php if(empty($items))ff_empty(); ?></section><dialog id="gallery-dialog" class="gallery-modal"><div class="dialog-heading"><span><?=e(t('gallery'))?></span><button class="icon-button" data-dialog-close type="button" aria-label="<?=e(t('close'))?>"><?=ff_icon('close')?></button></div><img alt="" width="1000" height="700" data-gallery-image><div class="lightbox-bottom"><button class="button small secondary" type="button" data-gallery-prev aria-label="<?=e(t('previous_image'))?>">←</button><p data-gallery-text></p><button class="button small secondary" type="button" data-gallery-next aria-label="<?=e(t('next_image'))?>">→</button></div></dialog>
